MainComponent::~MainComponent(){stopTimer();settings.save(engine.parameters());setLookAndFeel(nullptr);}
void MainComponent::addParameter(const juce::String&name,double lo,double hi,double step,std::atomic<float>&value){auto*l=parameterLabels.add(new juce::Label({},name));styleLabel(*l,13,theme::muted);auto*s=parameterSliders.add(new juce::Slider(juce::Slider::LinearHorizontal,juce::Slider::TextBoxRight));s->setRange(lo,hi,step);s->setValue(value.load(),juce::dontSendNotification);s->setTooltip(name);s->onValueChange=[s,&value]{value.store((float)s->getValue());};details.addAndMakeVisible(l);details.addAndMakeVisible(s);}
void MainComponent::showPage(int p){currentPage=p;sidebar.setSelected(p);const bool library=p==0||p==1||p==2||p==3||p==4||p==6;devices.setVisible(p==5);settingsPage->setVisible(p==8);diagnosticText.setVisible(p==7);copyDiagnostic.setVisible(p==7);viewport.setVisible(library);details.setVisible(library);for(auto*c:cards)c->setVisible(library&&p!=2);for(auto*c:effectCards)c->setVisible(library&&p==2);bannerTitle.setVisible(false);bannerText.setVisible(false);configure.setVisible(false);for(auto*b:tabs)b->setVisible(library);for(int i=0;i<tabs.size();++i)tabs[i]->setColour(juce::TextButton::buttonColourId,i==(p==2?1:0)?theme::blue:juce::Colours::transparentBlack);for(auto*b:chips)b->setVisible(library);const juce::StringArray names{"Visao geral","Biblioteca de Vozes","Biblioteca de Efeitos","Painel de Som","Equalizador","Dispositivos","Presets","Diagnostico","Configuracoes"};pageTitle.setText(names[p],juce::dontSendNotification);pageTitle.setVisible(p!=8);categoryFilter="Todos";filterCards();resized();repaint();}
void MainComponent::applyPreset(int i){selectedCard=i;for(int n=0;n<cards.size();++n)cards[n]->setSelected(n==i);const auto name=cards[i]->presetName();juce::String factory=name;if(name=="Voz Limpa")factory="Voz normal limpa";else if(name=="Grave Profunda"||name=="Grave Suave")factory="Masculina grave";else if(name=="Aguda")factory="Personagem infantil";else if(name=="Robo Pesado"||name=="Voz Metalica"||name=="Som Digital")factory="Robô";else if(name=="Radio")factory="Rádio policial";else if(name=="Eco Espacial")factory="Alienígena";presets.load(factory,engine.parameters());selectedName.setText(name,juce::dontSendNotification);selectedCategory.setText("Preset aplicado ao processamento",juce::dontSendNotification);auto&p=engine.parameters();const float values[]{p.mix.load(),p.pitchSemitones.load(),p.formant.load(),p.outputGainDb.load(),p.reverb.load(),p.distortion.load()};for(int n=0;n<parameterSliders.size();++n)parameterSliders[n]->setValue(values[n],juce::dontSendNotification);notification.showMessage("Preset carregado: "+name);}
void MainComponent::filterCards(){const auto q=search.getText().trim();int visible=0;auto filter=[&](VoiceCardComponent*c,bool page){const bool textOk=q.isEmpty()||c->presetName().containsIgnoreCase(q);const bool catOk=categoryFilter=="Todos"||c->presetCategory().containsIgnoreCase(categoryFilter);c->setVisible(page&&textOk&&catOk);if(c->isVisible())++visible;};for(auto*c:cards)filter(c,currentPage!=2);for(auto*c:effectCards)filter(c,currentPage==2);cardCanvas.setSize(juce::jmax(400,viewport.getWidth()-12),juce::jmax(viewport.getHeight(),((visible+4)/5)*170));resized();}
