void MainComponent::timerCallback(){const auto in=engine.processor().inputPeak(),out=engine.processor().outputPeak();meter.setLevels(in,out);auto*d=engine.deviceManager().getCurrentAudioDevice();deviceName.setText(d?"Entrada: "+d->getName():"Dispositivo indisponivel",juce::dontSendNotification);deviceStatus.setButtonText(d?"Conectado":"Sem audio");deviceStatus.setColour(juce::TextButton::buttonColourId,d?theme::panel:theme::red.darker(.3f));power.setButtonText(engine.isRunning()?"DESLIGAR":"LIGAR");mute.setButtonText(engine.parameters().muted.load()?"REATIVAR":"SILENCIAR");status.setText(engine.isRunning()?(engine.parameters().muted.load()?"Microfone silenciado":"Modificador ativo"):"Modificador desligado",juce::dontSendNotification);status.setColour(juce::Label::textColourId,engine.isRunning()?theme::green:theme::muted);double latency=0;if(d&&d->getCurrentSampleRate()>0)latency=1000.0*(d->getInputLatencyInSamples()+d->getOutputLatencyInSamples()+d->getCurrentBufferSizeSamples())/d->getCurrentSampleRate();cpuLatency.setText("CPU "+juce::String(engine.cpuUsage()*100,1)+"%  -  "+(d?juce::String(latency,1)+" ms":"Latencia indisponivel"),juce::dontSendNotification);if(currentPage==7)diagnosticText.setText(DiagnosticsManager::report(engine),false);}
